:root {
  --paper: #fffdf7;
  --ink: #26323d;
  --accent: #e76f51;
}

.game-card {
  box-sizing: border-box;
  width: 460px;
  padding: 16px;
  background: var(--paper);
  border: 2px solid var(--ink);
  border-radius: 14px;
  color: var(--ink);
}

.game-card header {
  display: flex;
  align-items: center;
  gap: 12px;
}

.game-icon {
  display: grid;
  width: 42px;
  height: 42px;
  place-items: center;
  background: var(--accent);
  border-radius: 10px;
  font-size: 23px;
}

.game-card h1 {
  margin: 0;
  font-size: 20px;
  line-height: 1.1;
}

.game-card p {
  margin: 4px 0 0;
  font-size: 14px;
  opacity: 0.72;
}

.return-date {
  margin-top: 14px !important;
  padding: 9px 11px;
  background: var(--accent);
  border-radius: 8px;
  color: var(--paper);
  font-weight: 700;
  opacity: 1 !important;
}

.game-card footer {
  margin-top: 12px;
  padding-top: 10px;
  border-top: 1px solid var(--ink);
  font-size: 12px;
  opacity: 0.72;
}
